-- Northern Barrens: creature abilities
-- Most of the zone's creatures had no AI or ran classic rows. The Northern Barrens are the Cataclysm revamp, so port their abilities
-- from the Cataclysm data, and from the classic data where Cataclysm has none (the zhevras, plainstriders and giraffes, Savannah
-- Prowlers, the Venture Co. at the Sludge Fen, hyenas and Kolkar Packhounds), keeping the scripts already in place, such as the
-- Sunscale raptors' egg escort.

SET @ENTRIES := '3241,3242,3244,3245,3246,3248,3255,3256,3265,3268,3270,3271,3275,3276,3278,3279,3280,3282,3283,3284,3286,3295,3338,3380,3382,3383,3384,3385,3386,3396,3398,3415,3425,3426,3452,3461,3470,3471,3501,3638,3672,3939,3986,4127,4316,5629,5829,5835,5842,6606,7288,7308,7310,14717,14893,33193,33201,34504,34544,34545,34560,34640,34706,34707,34733,34747,34752,34753,34790,34846,38659,38661,44164';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '3475,3652,20797,33195,51815,51914';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
